-- External/manual signature evidence registration; NOT an electronic approval mechanism.
CREATE TABLE manual_signature_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, organization_id BIGINT UNSIGNED NOT NULL, doc_type VARCHAR(16) NOT NULL, entity_id BIGINT UNSIGNED NOT NULL, evidence_reference VARCHAR(255) NULL, received_at DATETIME NOT NULL, recorded_by BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX ix_manual_signature(organization_id,doc_type,entity_id), FOREIGN KEY(organization_id) REFERENCES organizations(id), FOREIGN KEY(recorded_by) REFERENCES users(id)) ENGINE=InnoDB;
